import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"睽","description":"焦氏易林注 - 睽","frontmatter":{"title":"睽","description":"焦氏易林注 - 睽"},"headers":[],"relativePath":"zh/classics/jiaoyilin/038.md","filePath":"zh/classics/jiaoyilin/038.md"}'),l={name:"zh/classics/jiaoyilin/038.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="睽" tabindex="-1">睽 <a class="header-anchor" href="#睽" aria-label="Permalink to “睽”">​</a></h1><h3 id="睽-1" tabindex="-1">睽 <a class="header-anchor" href="#睽-1" aria-label="Permalink to “睽”">​</a></h3><h3 id="睽之乾" tabindex="-1">睽之乾 <a class="header-anchor" href="#睽之乾" aria-label="Permalink to “睽之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>被服文衣，游觀酒池。上堂見觴，喜為吾兄，使我憂亡。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此兼用遇卦象。乾為衣，睽互離為文，坎為酒、為憂，兌為池。○觀，汲古作視，依宋元本。</p><h3 id="睽之坤" tabindex="-1">睽之坤 <a class="header-anchor" href="#睽之坤" aria-label="Permalink to “睽之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>邑薑叔子，天文在手。實沈參虛，封為晉侯。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《恆》。</p><h3 id="睽之屯" tabindex="-1">睽之屯 <a class="header-anchor" href="#睽之屯" aria-label="Permalink to “睽之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>改柯易葉，飯溫不食。豪雄爭強，先者受福。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為柯葉，坤殺，故更改。坎為飲食，下有艮火，故曰飯溫，坤閉故不食。震為雄強、為福，初至五正反震，故曰爭強。</p><h3 id="睽之蒙" tabindex="-1">睽之蒙 <a class="header-anchor" href="#睽之蒙" aria-label="Permalink to “睽之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>馨香陟降，明德上登。社神佑顧，命予大鄰。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>伏巽為臭，故曰馨香，二至上正反震，故曰陟降。艮為明，震為德、為登，艮陽在上，故曰上登。坤為社，震為神，艮為顧，伏巽為命，震為鄰，震言，故曰命予大鄰。○予，汲古作為，依宋元本。</p><h3 id="睽之需" tabindex="-1">睽之需 <a class="header-anchor" href="#睽之需" aria-label="Permalink to “睽之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>老狼白獹，長尾大胡。前顛卻躓，進艮遇祟。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>此用《伏》象。艮為狼，下坤故曰老狼。獹，犬也。艮為犬，故曰白獹。艮為尾、為胡。胡，領肉下垂也，艮形長，故曰長尾大胡，坎陷故前顛卻躓。《詩》&quot;狼跋其尾&quot; &quot;狼跋其胡&quot;是也。○獹，宋元本作驢，汲古作駒，胡皆作狐，均非，依《震》之《恆》校。</p><h3 id="睽之訟" tabindex="-1">睽之訟 <a class="header-anchor" href="#睽之訟" aria-label="Permalink to “睽之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>山沒邱浮，陸為水魚，燕雀無廬。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《大有》。</p><h3 id="睽之師" tabindex="-1">睽之師 <a class="header-anchor" href="#睽之師" aria-label="Permalink to “睽之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>懿公淺愚，不受深謀。無援失國，為狄所賊。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《家人》。○賊，汲古作滅，依宋元本。</p><h3 id="睽之比" tabindex="-1">睽之比 <a class="header-anchor" href="#睽之比" aria-label="Permalink to “睽之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>鼎煬其耳，熱不可舉。大塗塞壅，旅人心苦。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《中孚》。○煬，汲古作易，依宋元本。</p><h3 id="睽之小畜" tabindex="-1">睽之小畜 <a class="header-anchor" href="#睽之小畜" aria-label="Permalink to “睽之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>凶聲醜言，惡不可聞。君子舍之，往恨我心。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。坤為凶、為醜，震為聲、為言，坎為聞，坤惡故不可聞。艮為君子。坎為恨、為心。○惡，汲古作要，依宋元本。</p><h3 id="睽之履" tabindex="-1">睽之履 <a class="header-anchor" href="#睽之履" aria-label="Permalink to “睽之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>昧暮乘車，履危蹈溝。亡失群物，摧折兩軸。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>見前。蹈，宋元本作陷，非，依汲古。</p><h3 id="睽之泰" tabindex="-1">睽之泰 <a class="header-anchor" href="#睽之泰" aria-label="Permalink to “睽之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>南有嘉魚，駕黃取。魴鱮詡詡，利來無憂。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《離》之《中孚》。</p><h3 id="睽之否" tabindex="-1">睽之否 <a class="header-anchor" href="#睽之否" aria-label="Permalink to “睽之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>隔在九山，往來勞難。心結不通，失其所歡。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為山，乾數九，故曰九山，艮止故曰隔。坤役萬物，故曰勞難。坤為心、為失，坤閉故不通。震為歡，二至四震覆，故不歡。</p><h3 id="睽之同人" tabindex="-1">睽之同人 <a class="header-anchor" href="#睽之同人" aria-label="Permalink to “睽之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>下流難居，狂夫多疲。貞良溫柔，年歲不富。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。坤水坎水，一陽在下，故曰下流難居。震為夫、為狂，坤柔故曰疲，坎冬故曰貞。坤為年歲，坤窮故曰不富。○狂夫，汲古訛任夫。疲，汲古作態，依宋元本。</p><h3 id="睽之大有" tabindex="-1">睽之大有 <a class="header-anchor" href="#睽之大有" aria-label="Permalink to “睽之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>狐狸雉兔，畏人逃去。分首竄匿，不知所處。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。離為雉，艮坎皆為狐狸。坎為畏，坎隱伏故曰逃去，曰竄匿。坎為首，乾亦為首，乾在下，坎伏，故曰分首竄匿。○首，宋元本作走，依汲古。</p><h3 id="睽之謙" tabindex="-1">睽之謙 <a class="header-anchor" href="#睽之謙" aria-label="Permalink to “睽之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>異體殊俗，各有所屬。西鄰孤嫗，欲寄我室。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>主母罵詈，終不可得。坤為體、為俗，中為一陽所隔，故曰異體殊俗。伏兌為西，震為鄰，巽為寡，故曰西鄰孤嫗。互坎為室，艮止，故曰欲寄我室。震為主，坤為母，正反震相背，故曰罵詈。艮為終。</p><h3 id="睽之豫" tabindex="-1">睽之豫 <a class="header-anchor" href="#睽之豫" aria-label="Permalink to “睽之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>怒非怨妬，貪得腐鼠。而呼鷹鸇，自令失餌，致被困患。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為怒，坎為妬、為鼠，伏巽故曰腐鼠。震為呼，艮為鷹鸇，坤為失，震為餌，坎為困，言自得腐鼠而呼鷹鸇，致為所奪，語襲莊子。○鷹，宋元本作鵲，依汲古。致作倒，依宋元本。</p><h3 id="睽之隨" tabindex="-1">睽之隨 <a class="header-anchor" href="#睽之隨" aria-label="Permalink to “睽之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>五心六意，歧道多怪。非君本心，生我恨悔。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>巽卦數五，互坎為心意，數六故曰五心六意。艮為道路，正反艮故曰歧道。坎為怪，互大坎故曰多怪。震為君、為生，坎為心、為恨。○心，宋元本作志，依汲古。</p><h3 id="睽之蠱" tabindex="-1">睽之蠱 <a class="header-anchor" href="#睽之蠱" aria-label="Permalink to “睽之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>三班六黑，同室共食。日長月息，我家有德。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>楚人呼虎為班，艮為虎，數三，故曰三班。黑，豕也。《詩小雅》&quot;以其騂黑&quot;傳：黑，豕也。巽為豕，艮為室，兌為貪、為月，艮為日、為家，震為息，言德能感物使虎豕同居也。</p><h3 id="睽之臨" tabindex="-1">睽之臨 <a class="header-anchor" href="#睽之臨" aria-label="Permalink to “睽之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>方船備水，旁河然火，終身無禍。震為船，坤方，故曰方船。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>方，並也。坤為水、為河，伏艮為火、為終，坤為身、為禍，震解故無禍，言有船則無水患，旁河則無火患也。</p><h3 id="睽之觀" tabindex="-1">睽之觀 <a class="header-anchor" href="#睽之觀" aria-label="Permalink to “睽之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>翳屏獨語，不聞朝市上。以利居服，兔跛後閗。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為屏，坤為寡，故曰獨，伏兌為語，巽為翳，翳屏獨語，隔屏獨語也。坤為朝市、為利，兌為耳，兌覆故不聞。艮為居，震為兔，兌折故曰兔跛。○以利，汲古作利以，兔跛後閗作究被後門，垮，依宋元本。</p><h3 id="睽之噬嗑" tabindex="-1">睽之噬嗑 <a class="header-anchor" href="#睽之噬嗑" aria-label="Permalink to “睽之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>居處不安，徙反觸患。艮為居處，正反艮故不安。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為徙，前與坎遇故曰觸患。○徙，汲古作徒，依宋元。</p><h3 id="睽之賁" tabindex="-1">睽之賁 <a class="header-anchor" href="#睽之賁" aria-label="Permalink to “睽之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>剠刖髠劓，子所賤棄。批捍之言，我心不快。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>通《困》。兌上缺故曰剠，巽下斷故曰刖，巽寡髪故曰髠。艮為鼻，兌上缺故曰鼻。震為人、為言，艮手，故曰批捍。批捍之言，猶打之使言也。坎為心、為憂，故不快。</p><h3 id="睽之剝" tabindex="-1">睽之剝 <a class="header-anchor" href="#睽之剝" aria-label="Permalink to “睽之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>阜田禾黍，堆壤麻枲。衣食我躬，室家饒有。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為阜，坤為田、為茅茹，故曰禾黍、曰麻枲。艮為堆壤，坤為衣，伏兌為食，艮為躬、為室家，坤多，故曰饒有。麻枲可以為衣，禾黍可食，故曰衣食我躬。○堆，宋元本作槌，依汲古。枲，各本皆訛阜，從王校。</p><h3 id="睽之復" tabindex="-1">睽之復 <a class="header-anchor" href="#睽之復" aria-label="Permalink to “睽之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>兩目失明，日奪無光。脛足跛倚，不可以行，頓於丘旁。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>此兼用遇卦《睽》象。睽重離故曰兩目，坎黑故失明。離為日光，為坎所奪故無。震為脛足，坤敝，故跛倚不行，坤閉故頓於丘旁。震為陵丘。</p><h3 id="睽之無妄" tabindex="-1">睽之無妄 <a class="header-anchor" href="#睽之無妄" aria-label="Permalink to “睽之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>金城朔方，外國多半。履霜不時，去復為憂。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為城，乾金，故曰金城，乾西北故曰朔方，金城，亦西北郡也。伏坤為國，在外卦故曰外國。震為羊，正覆震，故曰多羊。坤初為霜，初震爻故曰履霜。艮為時，正反艮故不時。伏坤為憂，去復為憂者，言震往與坤遇也。</p><h3 id="睽之大畜" tabindex="-1">睽之大畜 <a class="header-anchor" href="#睽之大畜" aria-label="Permalink to “睽之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>匿病不醫，亂政傷災。紂作淫虐，商破其墟。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>通《萃》。坤為病，巽為伏匿，艮止，故曰匿病不醫。坤為政、為亂、為災、為惡，故曰紂。坤為虐、為墟，兌為破，震為子，震覆，故曰商破其墟。商，子姓也。○病，汲古作痼，傷作生，均依宋元本。</p><h3 id="睽之頤" tabindex="-1">睽之頤 <a class="header-anchor" href="#睽之頤" aria-label="Permalink to “睽之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>鬼哭泣社，悲傷無後。甲子昧爽，殷人絕嗣。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為社、為鬼，震為哭、為後，艮為覆震，故無後。震為子，在東方故曰甲子，震為旦，故曰昧爽。震為子，殷，子姓，坤殺故殷人絕嗣。按：《論衡》雲：世稱紂之時，鬼郊夜哭，又曰紂郊鬼哭，即所謂鬼哭泣社也。又《墨子非攻》下雲商王紂之時，婦妖宵出，有鬼宵吟。○社，宋元本作柱，從汲古。人字，汲古作湯，從宋元本。</p><h3 id="睽之大過" tabindex="-1">睽之大過 <a class="header-anchor" href="#睽之大過" aria-label="Permalink to “睽之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>猋風卒起，車馳揭揭。棄古追亡，失其和節，憂心惙惙。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>正反巽故曰猋風。猋風，迴風也。《月令》&quot;猋風暴雨絕至&quot;註：迴風曰猋。伏震為車、為馳，乾為古，大過死故曰棄古、曰追亡。伏坤為失、為憂、為心。按：《詩檜風》：&quot;匪風發兮，匪車偈兮&quot;，《傳》雲&quot;偈偈疾驅&quot;，茲作揭揭，是齊詩與毛異字。又按此詩思周道而作，棄古追亡者，言見今之人棄周道而蹈滅亡之道也。</p><h3 id="睽之坎" tabindex="-1">睽之坎 <a class="header-anchor" href="#睽之坎" aria-label="Permalink to “睽之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>耄老失明，聞善不從。自令顛沛，反為咎殃。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>互艮為明、為耄老，坎黑故失明。坎耳為聞，互震為善、為從，艮止故曰不從。○反，宋元本作敗，依汲古。</p><h3 id="睽之離" tabindex="-1">睽之離 <a class="header-anchor" href="#睽之離" aria-label="Permalink to “睽之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>隨風騎龍，與利相逢。田獲三狐，商伯有功。衝衝之邑，長安無他。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>互巽為風，伏震為龍，巽為利。震為田獲，艮為狐，數三，故曰三狐。震為伯、為商旅，艮為邑、為安。○田，汲古訛日，依宋元本。</p><h3 id="睽之咸" tabindex="-1">睽之咸 <a class="header-anchor" href="#睽之咸" aria-label="Permalink to “睽之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>三牛五牂，重明作福。使我有得，疾入官獄，憂在心腹。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為牛，數三，故曰三牛。兌為羊，巽卦數五，故曰五牂。互乾為大明，艮亦為明，故曰重明。艮為官，伏坤為憂、為疾、為心腹，坤閉故曰入獄。○牂，汲古作，依宋元本。入，宋元本訛人，依汲古。</p><h3 id="睽之恒" tabindex="-1">睽之恒 <a class="header-anchor" href="#睽之恒" aria-label="Permalink to “睽之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>孟巳己醜，哀呼尼父。明德訖終，亂害滋起。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽居巳，巳四月為孟夏，故曰孟巳。巽貞醜，故曰已醜。《左傳哀十六年》四月己醜孔丘卒，公誄之曰：嗚呼哀哉尼父。乾為父、為山，故曰尼父。兌口為呼，乾為明德，伏坤為死，故曰訖終、曰亂虐。○己醜，各本多作乙醜，與左傳不符，依《歸妹》之《夬》校。害，汲古作虐，依宋元本。</p><h3 id="睽之遯" tabindex="-1">睽之遯 <a class="header-anchor" href="#睽之遯" aria-label="Permalink to “睽之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>華燈百枝，消暗衰微。精光訖盡，奄如灰糜。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為大明、為百，艮亦為明，巽為枝，故曰華燈百枝，陰消陽故衰盡。糜，爛也。《孟子》&quot;糜爛其民&quot;。巽消象也。</p><h3 id="睽之大壯" tabindex="-1">睽之大壯 <a class="header-anchor" href="#睽之大壯" aria-label="Permalink to “睽之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>鷹飛雉退，兔伏不起。狐張狼鳴，野雞駭驚。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。艮為鷹，坤文為雉，艮上故曰鷹飛，坤下故曰雉退。震為兔，巽伏故曰兔伏不起。艮為狐狼，震為張、為鳴，巽為雞，坤為野，故曰野雞。震為驚駭。○狐，宋元本作弧，非，依汲古。退，汲古作遽，駭驚作驚駭，失韻，均依宋元本。</p><h3 id="睽之晉" tabindex="-1">睽之晉 <a class="header-anchor" href="#睽之晉" aria-label="Permalink to “睽之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>鬬戰天門，身有何患。室傢具在，不失其歡。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>《內經》以戌亥為天門。艮為刀兵，居戌亥為天、為門，故曰天門。坤為身、為患，坎為室，艮為家。</p><h3 id="睽之明夷" tabindex="-1">睽之明夷 <a class="header-anchor" href="#睽之明夷" aria-label="Permalink to “睽之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>東家殺牛，行逆腥臊。神背西顧，命衰絕周。亳社災燒，宋人夷誅。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《巽》。震為周，坤為社，下離故曰災。艮為宋，坤殺故夷誅。</p><h3 id="睽之家人" tabindex="-1">睽之家人 <a class="header-anchor" href="#睽之家人" aria-label="Permalink to “睽之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>陰陽辨舒，二姓相合。婚姻孔雲，生我利福。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>坎為合，巽為利。二姓謂離坎。</p><h3 id="睽之睽" tabindex="-1">睽之睽 <a class="header-anchor" href="#睽之睽" aria-label="Permalink to “睽之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>倉盈庾億，宜稼黍稷，年歲有息。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《師》。</p><h3 id="睽之蹇" tabindex="-1">睽之蹇 <a class="header-anchor" href="#睽之蹇" aria-label="Permalink to “睽之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>東入海口，循流北走。一高一下，五邑無主。十日六夜，死於水涘。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>離為東，坤為海，伏兌為口，坎入坤中故曰東入海口。坎為流，重坎故曰循流，坎北故北走。艮高，坎下卦一陰一陽相間，故曰一高一下。坎納戊，數五，艮為邑，震為主，震覆，故五邑無主。伏兌數十，故曰十日坎為夜，數六，故曰六夜。坎為死卦，故曰死於水涘。</p><h3 id="睽之解" tabindex="-1">睽之解 <a class="header-anchor" href="#睽之解" aria-label="Permalink to “睽之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>孤竹之墟，失婦無夫。傷於蒺藜，不見其妻。東郭棠薑，武子以亡。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《剝》。</p><h3 id="睽之損" tabindex="-1">睽之損 <a class="header-anchor" href="#睽之損" aria-label="Permalink to “睽之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>天門東墟，盡既為災。跰喑聾，秦伯受殃。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮居戌亥為天門，震為東，坤為墟、為災。跰，足互貌。震為足，兌為口、為耳，坤閉故曰喑、曰聾。喑，失音也。震為伯，兌西故曰秦伯。義多不解。</p><h3 id="睽之益" tabindex="-1">睽之益 <a class="header-anchor" href="#睽之益" aria-label="Permalink to “睽之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>賴先休光，受福之祉。雖遭亂潰，獨不危殆。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>伏乾為先、為休、為光、為福祉，坤為亂潰、為危殆，震解故不危殆。殆，古音以。</p><h3 id="睽之夬" tabindex="-1">睽之夬 <a class="header-anchor" href="#睽之夬" aria-label="Permalink to “睽之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>折若蔽日，不風稚叔。三足孤烏，遠其元夫。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《蒙》。○若，汲古作葉，非。</p><h3 id="睽之姤" tabindex="-1">睽之姤 <a class="header-anchor" href="#睽之姤" aria-label="Permalink to “睽之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>二人同室，兄弟合食。和樂相好，各得所欲。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為人，坤數二，故曰二人。坤為室，震為口，故曰食。震為樂。○欲，宋元本作敬，依汲古。</p><h3 id="睽之萃" tabindex="-1">睽之萃 <a class="header-anchor" href="#睽之萃" aria-label="Permalink to “睽之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>繼體守藩，縱欲廢賢。君臣淫佚，夏氏失身。側室之門，福祿來存。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為體，艮為藩，乾為賢，乾伏故曰廢賢。乾為君，坤為臣，正反震故曰縱欲、曰淫佚。巽為夏，坤為身、為失，故曰夏氏失身。艮為室，兌毀，故曰側室。坤為門，乾為福祿，此似指陳靈公君臣通夏姬事。</p><h3 id="睽之升" tabindex="-1">睽之升 <a class="header-anchor" href="#睽之升" aria-label="Permalink to “睽之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>老狐屈尾，東西為鬼。病我長女，哭涕屈指。或西或東，大華易誘。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>通《無妄》。艮為狐、為尾，正反艮，故曰屈尾。震東兌西，坤為鬼、為病，巽為長女。兌為哭涕，艮為指，艮覆故曰屈指。此似述狐祟人故事，自莊子即有孽狐為祥之語，《虞初志》亡後不得其詳耳。○哭，宋元本作坐，依汲古。華，汲古作革，依宋元本。恐仍有訛，然太華為近。</p><h3 id="睽之困" tabindex="-1">睽之困 <a class="header-anchor" href="#睽之困" aria-label="Permalink to “睽之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>大樹之子，百條共母。當夏六月，枝葉茂盛。鸞鳳以庇，召伯避暑。翩翩偃仰，各得其所。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>第七句依《大過》之《需》校，各本皆作穉穉卭甚，恐非。</p><h3 id="睽之井" tabindex="-1">睽之井 <a class="header-anchor" href="#睽之井" aria-label="Permalink to “睽之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>井堙木刊，國多暴殘。秦王失戍，壞我太壇。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>兌為井，坎為塞，故曰井堙。巽為隕落，故曰木刊。伏艮為國，震為暴、為王，兌西故曰秦王。戍，守也。艮為守，艮伏故曰失戍。太壇者，社稷，言秦社稷之壞由於謫戍也。</p><h3 id="睽之革" tabindex="-1">睽之革 <a class="header-anchor" href="#睽之革" aria-label="Permalink to “睽之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>駕黃賈蒼，與利相迎。心獲所守，不累弟兄。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為馬、為黃、為蒼，巽為利，震巽相往複故曰相迎。坎為心，艮為守、為弟，震為兄。</p><h3 id="睽之鼎" tabindex="-1">睽之鼎 <a class="header-anchor" href="#睽之鼎" aria-label="Permalink to “睽之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>倉盈庾億，宜稼黍稷。年豐歲熟，民得安息。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《師》。</p><h3 id="睽之震" tabindex="-1">睽之震 <a class="header-anchor" href="#睽之震" aria-label="Permalink to “睽之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>龍生馬淵，壽考且神。飛勝上天，舍宿軒轅。居常樂安。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為龍、為馬、為神，坤為淵，艮為壽考、為天、為星，故曰舍宿軒轅。《史記天官書》&quot;軒轅十二星&quot;。○龍，各本皆作人，依《未濟》之《歸妹》校。考，宋本作若，依元本。馬淵指坤，坤初變震，故曰龍生馬淵。</p><h3 id="睽之艮" tabindex="-1">睽之艮 <a class="header-anchor" href="#睽之艮" aria-label="Permalink to “睽之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>思顧所之，今乃逢時。洗濯故憂，拜我歡來。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互坎為思，震為之，艮為顧、為時，坎為洗濯、為憂，震為歡。○濯，各本多作我，依《節》之《震》校。</p><h3 id="睽之漸" tabindex="-1">睽之漸 <a class="header-anchor" href="#睽之漸" aria-label="Permalink to “睽之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>魁罡所當，初為敗殃。君子流連，困於水漿。求金東山，利在代鄉。賈市有息，子載母行。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為星，故曰魁罡。《參同契》：&quot;二月榆魁臨於卯，麥生天罡據西&quot;註，天罡即北斗。《夢溪筆談》&quot;鬥杓謂之剛&quot;。《史記天官書》：&quot;魁枕參首&quot;註：魁，北斗第一星也。《渙》之《比》雲&quot;行觸天罡，馬死車傷&quot;，是罡星所指之地凶也。巽隕落故敗。艮為君子，坎為水漿，坎陷故困。艮為金、為求、為山，離位東，故曰東山。巽為利市、為母，伏震為子。</p><h3 id="睽之歸妹" tabindex="-1">睽之歸妹 <a class="header-anchor" href="#睽之歸妹" aria-label="Permalink to “睽之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>鉛刀攻玉，無不鑽鑿。龍體具舉，魯般為輔。三聖翼事，所求必喜。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>通《漸》。艮為刀，巽柔故曰鉛刀。震為玉、為龍，艮手為鑽鑿，兌為魯，故曰魯般。坎為聖，震數三，故曰三聖。震為羽翼、為喜。○具，宋元本作其，般作班，依汲古。</p><h3 id="睽之豐" tabindex="-1">睽之豐 <a class="header-anchor" href="#睽之豐" aria-label="Permalink to “睽之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>喜來如雲，舉家蒙歡。眾才君子，駕福盈門。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《渙》。震為喜，坎為雲，艮為家、為君子、為門，坎為眾，震為駕、為福。○蒙歡，汲古作歡忻，從宋元本。</p><h3 id="睽之旅" tabindex="-1">睽之旅 <a class="header-anchor" href="#睽之旅" aria-label="Permalink to “睽之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>響像無形，骨體不成。微行衰索，消滅無名。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>巽風響而無形，艮為體、為名，巽伏故無名。</p><h3 id="睽之巽" tabindex="-1">睽之巽 <a class="header-anchor" href="#睽之巽" aria-label="Permalink to “睽之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>積水不溫，北陸苦寒。露宿多風，君子傷心。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏坎故曰積水、曰苦寒，坎北故曰北陸。坎為露、為宿，重巽故風多。艮為君子，坎為心。</p><h3 id="睽之兌" tabindex="-1">睽之兌 <a class="header-anchor" href="#睽之兌" aria-label="Permalink to “睽之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>黃馬綠車，駕之大都。贊達才能，使我無憂。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏震為玄黃、為馬、為車，兌西方，數四，九宮四色綠，故曰綠車。艮為都，重艮故曰大都。兌口故曰贊達。互巽為材，坎為憂，坎伏故無憂。</p><h3 id="睽之渙" tabindex="-1">睽之渙 <a class="header-anchor" href="#睽之渙" aria-label="Permalink to “睽之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>從風放火，艾芝俱死。三害積房，叔子中傷。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>巽風艮火，巽為艾芝，在火上故死。震數三，坎為害、為積，艮為房、為叔子，坎為中、為傷，《論衡》：&quot;身蒙三害，雖孔丘、墨翟不能自免&quot;。○房，汲古作聚，依宋元本。叔，宋元本作十，依汲古。</p><h3 id="睽之節" tabindex="-1">睽之節 <a class="header-anchor" href="#睽之節" aria-label="Permalink to “睽之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>一身三手，無益於輔。兩足共節，不能克敏。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為身，坎數一，故曰一身，震數三，艮手故曰三手。兌毀坎破，故無益於輔。正反震故曰兩足。艮多節，正反震故曰共節。節者，止也，故不能克敏。</p><h3 id="睽之中孚" tabindex="-1">睽之中孚 <a class="header-anchor" href="#睽之中孚" aria-label="Permalink to “睽之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>南向陋室，風雨併入。埃塵積濕，王母盲痹。偏枯心疾，亂我家次。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為南，艮為室，巽為敝漏，故曰陋室。巽風故起埃塵，兌雨故積濕。艮為埃塵，震為王，巽為母，故曰王母，互大離故曰盲。上風下濕故曰痹。痹，濕病也。巽枯在上故曰偏枯。○次，宋元本作資，依汲古。</p><h3 id="睽之小過" tabindex="-1">睽之小過 <a class="header-anchor" href="#睽之小過" aria-label="Permalink to “睽之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>採薇出車，魚麗思初。上下促急，君子懷憂。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>採薇、魚麗，皆《小雅》詩篇名，毛序謂美萬物盛多能備禮。鄭註：鄉飲酒雲，魚麗言太平年豐物多也，焦雲思初念初時之盛而今不然也，與毛鄭異，艮手為採巽為薇，震為車，巽為魚，震為初，艮上震下，風散兌毀，故曰上下促急。艮為君子。</p><h3 id="睽之既濟" tabindex="-1">睽之既濟 <a class="header-anchor" href="#睽之既濟" aria-label="Permalink to “睽之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>先易後否，告我利市。騷蘇自苦，思我故止。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>○吾，汲古作再，依宋元本。</p><h3 id="睽之未濟" tabindex="-1">睽之未濟 <a class="header-anchor" href="#睽之未濟" aria-label="Permalink to “睽之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>生宜地乳，上皇大喜。隆我福祉，貴壽無極。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此與上皆用半象。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
